let file = """{"version":3,"file":"modalUtil-CBKD30QK.js","names":[],"sources":["../../src/utils/searchAndReplace.ts","../../src/scripts/ui/utils.ts","../../src/scripts/utils.ts","../../src/utils/modalUtil.ts"],"sourcesContent":["import type { LGraph, Subgraph } from '@/lib/litegraph/src/litegraph'\nimport { formatDate } from '@/utils/formatUtil'\nimport { collectAllNodes } from '@/utils/graphTraversalUtil'\n\nexport function applyTextReplacements(\n  graph: LGraph | Subgraph,\n  value: string\n): string {\n  const allNodes = collectAllNodes(graph)\n\n  return value.replace(/%([^%]+)%/g, function (match, text) {\n    const split = text.split('.')\n    if (split.length !== 2) {\n      // Special handling for dates\n      if (split[0].startsWith('date:')) {\n        return formatDate(split[0].substring(5), new Date())\n      }\n\n      if (text !== 'width' && text !== 'height') {\n        // Dont warn on standard replacements\n        console.warn('Invalid replacement pattern', text)\n      }\n      return match\n    }\n\n    // Find node with matching S&R property name\n    let nodes = allNodes.filter(\n      (n) => n.properties['Node name for S&R'] === split[0]\n    )\n    // If we can't, see if there is a node with that title\n    if (!nodes.length) {\n      nodes = allNodes.filter((n) => n.title === split[0])\n    }\n    if (!nodes.length) {\n      console.warn('Unable to find node', split[0])\n      return match\n    }\n\n    if (nodes.length > 1) {\n      console.warn('Multiple nodes matched', split[0], 'using first match')\n    }\n\n    const node = nodes[0]\n\n    const widget = node.widgets?.find((w) => w.name === split[1])\n    if (!widget) {\n      console.warn('Unable to find widget', split[1], 'on node', split[0], node)\n      return match\n    }\n\n    return ((widget.value ?? '') + '').replaceAll(\n      // oxlint-disable-next-line no-control-regex\n      /[/?<>\\\\:*|\"\\x00-\\x1F\\x7F]/g,\n      '_'\n    )\n  })\n}\n","type Props = {\n  parent?: HTMLElement\n  $?: (el: HTMLElement) => void\n  dataset?: DOMStringMap\n  style?: Partial<CSSStyleDeclaration>\n  for?: string\n  textContent?: string\n  [key: string]: unknown\n}\n\ntype Children = Element[] | Element | string | string[]\n\ntype ElementType<K extends string> = K extends keyof HTMLElementTagNameMap\n  ? HTMLElementTagNameMap[K]\n  : HTMLElement\n\nexport function $el<TTag extends string>(\n  tag: TTag,\n  propsOrChildren?: Children | Props,\n  children?: Children\n): ElementType<TTag> {\n  const split = tag.split('.')\n  const element = document.createElement(split.shift() as string)\n  if (split.length > 0) {\n    element.classList.add(...split)\n  }\n\n  if (propsOrChildren) {\n    if (typeof propsOrChildren === 'string') {\n      propsOrChildren = { textContent: propsOrChildren }\n    } else if (propsOrChildren instanceof Element) {\n      propsOrChildren = [propsOrChildren]\n    }\n    if (Array.isArray(propsOrChildren)) {\n      element.append(...propsOrChildren)\n    } else {\n      const { parent, $: cb, dataset, style, ...rest } = propsOrChildren\n\n      if (rest.for) {\n        element.setAttribute('for', rest.for)\n      }\n\n      if (style) {\n        Object.assign(element.style, style)\n      }\n\n      if (dataset) {\n        Object.assign(element.dataset, dataset)\n      }\n\n      Object.assign(element, rest)\n      if (children) {\n        element.append(...(Array.isArray(children) ? children : [children]))\n      }\n\n      if (parent) {\n        parent.append(element)\n      }\n\n      if (cb) {\n        cb(element)\n      }\n    }\n  }\n  return element as ElementType<TTag>\n}\n\nexport type ClassList = string | string[] | Record<string, boolean>\n\nexport function applyClasses(\n  element: HTMLElement,\n  classList: ClassList,\n  ...requiredClasses: string[]\n) {\n  let str: string\n  if (typeof classList === 'string') {\n    str = classList\n  } else if (classList instanceof Array) {\n    str = classList.join(' ')\n  } else {\n    str = Object.entries(classList).reduce((p, c) => {\n      if (c[1]) {\n        p += (p.length ? ' ' : '') + c[0]\n      }\n      return p\n    }, '')\n  }\n  element.className = str\n  element.classList.add(...requiredClasses)\n}\n\nexport function toggleElement<T>(\n  element: HTMLElement,\n  {\n    onHide,\n    onShow\n  }: {\n    onHide?: (el: HTMLElement) => void\n    onShow?: (el: HTMLElement, value: NonNullable<T>) => void\n  } = {}\n) {\n  let placeholder: Comment | undefined\n  return (value: T) => {\n    if (value) {\n      if (placeholder) {\n        placeholder.replaceWith(element)\n        placeholder = undefined\n      }\n      onShow?.(element, value)\n    } else {\n      placeholder ??= document.createComment('')\n      element.replaceWith(placeholder)\n      onHide?.(element)\n    }\n  }\n}\n","import { applyTextReplacements as _applyTextReplacements } from '@/utils/searchAndReplace'\n\nimport { api } from './api'\nimport type { ComfyApp } from '@/types/comfy'\nimport { $el } from './ui/utils'\n\nexport function clone<T>(obj: T): T {\n  try {\n    if (typeof structuredClone !== 'undefined') {\n      return structuredClone(obj)\n    }\n  } catch {\n    // structuredClone is stricter than using JSON.parse/stringify so fallback to that\n  }\n\n  return JSON.parse(JSON.stringify(obj))\n}\n\n/**\n * @deprecated Use `applyTextReplacements` from `@/utils/searchAndReplace` instead\n * There are external callers to this function, so we need to keep it for now\n */\nexport function applyTextReplacements(app: ComfyApp, value: string): string {\n  return _applyTextReplacements(app.rootGraph, value)\n}\n\nexport async function addStylesheet(\n  urlOrFile: string,\n  relativeTo?: string\n): Promise<void> {\n  return new Promise((res, rej) => {\n    let url\n    if (urlOrFile.endsWith('.js')) {\n      url = urlOrFile.substr(0, urlOrFile.length - 2) + 'css'\n    } else {\n      url = new URL(\n        urlOrFile,\n        relativeTo ?? `${window.location.protocol}//${window.location.host}`\n      ).toString()\n    }\n    $el('link', {\n      parent: document.head,\n      rel: 'stylesheet',\n      type: 'text/css',\n      href: url,\n      onload: res,\n      onerror: rej\n    })\n  })\n}\n\nexport { downloadBlob } from '@/base/common/downloadUtil'\n\nexport function uploadFile(accept: string) {\n  return new Promise<File>((resolve, reject) => {\n    const input = document.createElement('input')\n    input.type = 'file'\n    input.accept = accept\n    input.onchange = (e) => {\n      const file = (e.target as HTMLInputElement).files?.[0]\n      if (!file) return reject(new Error('No file selected'))\n      resolve(file)\n    }\n    input.click()\n  })\n}\n\nexport function prop<T>(\n  target: object,\n  name: string,\n  defaultValue: T,\n  onChanged?: (\n    currentValue: T,\n    previousValue: T,\n    target: object,\n    name: string\n  ) => void\n): T {\n  let currentValue: T\n  Object.defineProperty(target, name, {\n    get() {\n      return currentValue\n    },\n    set(newValue) {\n      const prevValue = currentValue\n      currentValue = newValue\n      onChanged?.(currentValue, prevValue, target, name)\n    }\n  })\n  return defaultValue\n}\n\nexport function getStorageValue(id: string) {\n  const clientId = api.clientId ?? api.initialClientId\n  return (\n    (clientId && sessionStorage.getItem(`${id}:${clientId}`)) ??\n    localStorage.getItem(id)\n  )\n}\n\nexport function setStorageValue(id: string, value: string) {\n  const clientId = api.clientId ?? api.initialClientId\n  if (clientId) {\n    sessionStorage.setItem(`${id}:${clientId}`, value)\n  }\n  localStorage.setItem(id, value)\n}\n","function isRendered(element: Element): boolean {\n  return (\n    element.closest('[hidden], [aria-hidden=\"true\"]') === null &&\n    element.checkVisibility({ visibilityProperty: true })\n  )\n}\n\nfunction hasOpenRekaDialog(): boolean {\n  return Array.from(\n    document.querySelectorAll('[role=\"dialog\"][data-state=\"open\"]')\n  ).some(\n    (dialog) =>\n      dialog.closest('[data-reka-popper-content-wrapper]') === null &&\n      isRendered(dialog)\n  )\n}\n\nfunction hasOpenNativeDialog(): boolean {\n  return Array.from(document.querySelectorAll('dialog[open]')).some(isRendered)\n}\n\nfunction hasVisibleAriaModal(): boolean {\n  return Array.from(\n    document.querySelectorAll('[role=\"dialog\"][aria-modal=\"true\"]')\n  ).some(isRendered)\n}\n\nfunction hasVisibleLegacyModal(): boolean {\n  return Array.from(document.querySelectorAll('.comfy-modal')).some(isRendered)\n}\n\nexport function isModalOpen(managedDialogCount: number): boolean {\n  return (\n    managedDialogCount > 0 ||\n    hasVisibleAriaModal() ||\n    hasOpenRekaDialog() ||\n    hasOpenNativeDialog() ||\n    hasVisibleLegacyModal()\n  )\n}\n"],"mappings":"8NAIA,SAAgB,wBACd,EACA,EACQ,CACR,IAAM,EAAW,EAAgB,CAAK,EAEtC,OAAO,EAAM,QAAQ,aAAc,SAAU,EAAO,EAAM,CACxD,IAAM,EAAQ,EAAK,MAAM,GAAG,EAC5B,GAAI,EAAM,SAAW,EAUnB,OARI,EAAM,EAAE,CAAC,WAAW,OAAO,EACtB,EAAW,EAAM,EAAE,CAAC,UAAU,CAAC,EAAG,IAAI,IAAM,GAGjD,IAAS,SAAW,IAAS,UAE/B,QAAQ,KAAK,8BAA+B,CAAI,EAE3C,GAIT,IAAI,EAAQ,EAAS,OAClB,GAAM,EAAE,WAAW,uBAAyB,EAAM,EACrD,EAKA,GAHK,EAAM,SACT,EAAQ,EAAS,OAAQ,GAAM,EAAE,QAAU,EAAM,EAAE,GAEjD,CAAC,EAAM,OAET,OADA,QAAQ,KAAK,sBAAuB,EAAM,EAAE,EACrC,EAGL,EAAM,OAAS,GACjB,QAAQ,KAAK,yBAA0B,EAAM,GAAI,mBAAmB,EAGtE,IAAM,EAAO,EAAM,GAEb,EAAS,EAAK,SAAS,KAAM,GAAM,EAAE,OAAS,EAAM,EAAE,EAM5D,OALK,IAKI,EAAO,OAAS,IAAM,GAAA,CAAI,WAEjC,6BACA,GACF,GARE,QAAQ,KAAK,wBAAyB,EAAM,GAAI,UAAW,EAAM,GAAI,CAAI,EAClE,EAQX,CAAC,CACH,oDCxCA,SAAgB,IACd,EACA,EACA,EACmB,CACnB,IAAM,EAAQ,EAAI,MAAM,GAAG,EACrB,EAAU,SAAS,cAAc,EAAM,MAAM,CAAW,EAK9D,GAJI,EAAM,OAAS,GACjB,EAAQ,UAAU,IAAI,GAAG,CAAK,EAG5B,EAAiB,CAMnB,GALI,OAAO,GAAoB,SAC7B,EAAkB,CAAE,YAAa,CAAgB,EACxC,aAA2B,UACpC,EAAkB,CAAC,CAAe,GAEhC,MAAM,QAAQ,CAAe,EAC/B,EAAQ,OAAO,GAAG,CAAe,MAC5B,CACL,GAAM,CAAE,SAAQ,EAAG,EAAI,UAAS,QAAO,GAAG,GAAS,EAE/C,EAAK,KACP,EAAQ,aAAa,MAAO,EAAK,GAAG,EAGlC,GACF,OAAO,OAAO,EAAQ,MAAO,CAAK,EAGhC,GACF,OAAO,OAAO,EAAQ,QAAS